-- op-01: services depending on redis-west
SELECT 'op-01' as op, service_id FROM service_dependencies WHERE resource_id = 'redis-west';

-- op-02: capabilities for those services
SELECT 'op-02' as op, sc.capability_id FROM service_dependencies sd JOIN service_capabilities sc ON sd.service_id = sc.service_id WHERE sd.resource_id = 'redis-west';

-- op-03: teams for those services
SELECT 'op-03' as op, so.team_id FROM service_dependencies sd JOIN service_ownerships so ON sd.service_id = so.service_id WHERE sd.resource_id = 'redis-west';

-- op-04: tests for those services
SELECT 'op-04' as op, itc.test_id FROM service_dependencies sd JOIN integration_test_coverage itc ON sd.service_id = itc.service_id WHERE sd.resource_id = 'redis-west';

SELECT * FROM runbooks;
SELECT * FROM runbook_capability_coverage;
SELECT * FROM environments;

SELECT * FROM resources;
SELECT * FROM service_dependencies;
